`timescale 1ns/1ps
module ecc_secded_64(input logic [63:0] data_in,output logic [71:0] codeword_out,input logic [71:0] codeword_in,output logic [63:0] data_out,output logic single_error,double_error,corrected_error); integer pos,di,p; logic [71:0] enc,corr; logic [6:0] syndrome; logic overall_bad; function automatic logic parity_for_position(input integer parity_pos); integer k; logic x; begin x=0; for(k=1;k<=71;k=k+1) if((k&parity_pos)!=0)x=x^enc[k-1]; parity_for_position=x; end endfunction always_comb begin enc='0; di=0; for(pos=1;pos<=71;pos=pos+1) if(!((pos==1)||(pos==2)||(pos==4)||(pos==8)||(pos==16)||(pos==32)||(pos==64))) begin enc[pos-1]=data_in[di]; di=di+1; end for(p=1;p<=64;p=p*2) enc[p-1]=parity_for_position(p); enc[71]=^enc[70:0]; codeword_out=enc; end always_comb begin syndrome='0; corr=codeword_in; single_error=0; double_error=0; corrected_error=0; for(p=1;p<=64;p=p*2) for(pos=1;pos<=71;pos=pos+1) if((pos&p)!=0) syndrome[$clog2(p)]=syndrome[$clog2(p)]^codeword_in[pos-1]; overall_bad=^codeword_in; if(overall_bad&&(syndrome!=0)) begin if(syndrome<=71)corr[syndrome-1]=~corr[syndrome-1]; single_error=1; corrected_error=1; end else if(overall_bad&&(syndrome==0)) begin corr[71]=~corr[71]; single_error=1; corrected_error=1; end else if(!overall_bad&&(syndrome!=0)) double_error=1; di=0; data_out='0; for(pos=1;pos<=71;pos=pos+1) if(!((pos==1)||(pos==2)||(pos==4)||(pos==8)||(pos==16)||(pos==32)||(pos==64))) begin if(di<64)data_out[di]=corr[pos-1]; di=di+1; end end endmodule
